#!/usr/bin/env python3
"""Final micro-pass evidence/report; never generate QA answer labels."""
import csv,json,hashlib,sys,collections
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'Model'))
from product_compatibility import ProductMatchService,profile_from_query
from product_ontology import compatibility,norm
from export_micro_matcher_holdout import EXCLUSIONS,excluded_queries
P=ROOT/'data/matcher_micro_cleanup';H=ROOT/'data/matcher_micro_holdout'
def main():
 before=json.loads((P/'before_evaluation.json').read_text());after=json.loads((P/'after_evaluation.json').read_text());audit=json.loads((P/'root_causes.json').read_text());labels=list(csv.DictReader((ROOT/'data/matcher_final_holdout/final_holdout_assistant_labeled.csv').open()));byid={r['case_id']:r for r in map(json.loads,(P/'after_population.jsonl').open())};regs={r['case_id']:r for r in map(json.loads,(ROOT/'Model/evaluation/micro_holdout_regressions.jsonl').open())};s=ProductMatchService();outcomes=[];hits=collections.Counter();eligible=0;fn_accepted=0
 for case in audit['cases']:
  q,_=profile_from_query(case['ingredient_query'],s.overrides);reg=regs[case['case_id']];pid=reg['product_feature']['product_id'];gate=compatibility(q.ontology,s.identity_catalog.identities[pid]);now=byid[case['case_id']];old=case['before_query_ontology'];original_gates=next((r['gate_reasons'] for r in case['reference_candidates'] if r['product_id']==pid),[])
  stage='NORMALIZATION' if 'or ' in case['ingredient_query'].lower() and ('ambiguous_identity_or_variant' in json.loads(case['reason_codes']) or 'unknown_family' in json.loads(case['reason_codes'])) else 'ONTOLOGY' if old['family'] in (None,'prepared') else 'SCORING' if 'ambiguous_material_identity_margin' in json.loads(case['reason_codes']) else 'UNKNOWN_METADATA' if any('unverified_' in r for r in original_gates) else 'COMPATIBILITY'
  if case['review_label']=='SHOULD_HAVE_MATCHED' and not reg['expected_allowed'] and stage=='COMPATIBILITY':stage='UNKNOWN_METADATA'
  result={'case_id':case['case_id'],'ingredient_query':case['ingredient_query'],'original_label':case['review_label'],'original_product':case['selected_product'],'root_cause':case['root_cause'],'general_rule':case['general_rule'],'before_first_failure_stage':stage,'reference_product':reg['product_name'],'after_reference_gate_reasons':list(gate.reasons),'after_selected_product':(now['selected_match'] or {}).get('product_name'),'after_reason_codes':now['reason_codes'],'adjudication':reg['adjudication'],'new_selection_label':None}
  if case['review_label']=='WRONG':result['original_pair_blocked']=not gate.allowed;result['label_disagreement']=case['root_cause']=='OTHER'
  else:
   allowed=s.identity_catalog.candidate_ids(q.ontology);retrieval=s.retriever.retrieve_product_candidates(q.normalized_signature,limit=20,use_semantic=True,allowed_product_ids=allowed);ids=[c.product_id for c in retrieval.candidates];rank=ids.index(pid)+1 if pid in ids else None;eligible+=gate.allowed;fn_accepted+=bool(now['selected_match']);result['reference_rank']=rank
   result['after_first_failure_stage']='UNKNOWN_METADATA / COMPATIBILITY' if not gate.allowed else 'CANDIDATE RETRIEVAL' if not rank else 'SCORING / THRESHOLD / margin' if not now['selected_match'] else 'selected, unreviewed'
   for k in (5,10,20):hits[k]+=bool(rank and rank<=k)
  outcomes.append(result)
 (P/'material_case_outcomes.json').write_text(json.dumps(outcomes,indent=2)+'\n')
 # Preserve the strong cheese system against both historical reviewed cohorts.
 cheese=[]
 for file in ['data/matcher_structural_holdout/structural_holdout_assistant_labeled.csv','data/matcher_final_holdout/final_holdout_assistant_labeled.csv']:
  for row in csv.DictReader((ROOT/file).open()):
   if row['food_family']=='cheese':cheese.append({'case_id':row['case_id'],'query':row['ingredient_query'],'original_product':row['selected_product'],'after_product':(byid[row['case_id']]['selected_match'] or {}).get('product_name',''),'unchanged':row['selected_product']==(byid[row['case_id']]['selected_match'] or {}).get('product_name','')})
 (P/'cheese_control_outcomes.json').write_text(json.dumps(cheese,indent=2)+'\n')
 m=json.loads((H/'sample.json').read_text());rows=list(csv.DictReader((H/'review.csv').open()));assert len(rows)==len({norm(r['ingredient_query']) for r in rows})==300;assert all(not r['review_label'] for r in rows)
 overlaps={f:len({norm(r['ingredient_query']) for r in rows}&excluded_queries(ROOT/f)) for f in EXCLUSIONS};assert not any(overlaps.values());assert all(hashlib.sha256((ROOT/f).read_bytes()).hexdigest()==v for f,v in m['source_hashes'].items());assert all(hashlib.sha256((ROOT/f).read_bytes()).hexdigest()==v for f,v in m['exclusion_sources'].items());assert hashlib.sha256((H/'review.csv').read_bytes()).hexdigest()==m['review_csv_sha256'];assert hashlib.sha256((H/'population.jsonl').read_bytes()).hexdigest()==m['population_sha256']
 tests=json.loads((P/'separate_test_results.json').read_text());assert all(r['passed'] for r in tests.values());log=(P/'full_tests.log').read_text();assert 'Ran 495 tests' in log and log.strip().endswith('OK')
 verification={'count':300,'normalized_unique_queries':300,'labels_blank':True,'source_hashes_current':True,'csv_and_population_hashes_valid':True,'independently_recomputed_overlap_counts':overlaps};(P/'holdout_verification.json').write_text(json.dumps(verification,indent=2)+'\n')
 accepted=[r for r in labels if r['current_matcher_decision']=='accepted'];good=sum(r['review_label'] in ('CORRECT','ACCEPTABLE_SUBSTITUTE') for r in accepted);bad=sum(r['review_label']=='WRONG' for r in accepted);amb=sum(r['review_label']=='AMBIGUOUS' for r in accepted)
 summary={'recommendation':'STRUCTURAL_ISSUES_REMAIN','review_provenance':'assistant QA, not independent human certification','new_manual_metrics':None,'classified_nonfood_selected_count':after['selected_family_distribution'].get('nonfood',0),'original_accepted':len(accepted),'original_good':good,'original_wrong':bad,'original_ambiguous':amb,'root_cause_counts':audit['wrong_root_cause_counts'],'material_cases':71,'original_wrong_pairs_blocked':sum(r.get('original_pair_blocked',False) for r in outcomes),'label_disagreements':1,'new_regression_cases':71,'total_data_regressions':2015,'full_test_count':495,'separate_tests':tests,'formerly_rejected_FN_now_selected':fn_accepted,'candidate_recall_at_5_10_20':{f'at_{k}':hits[k]/33 for k in (5,10,20)},'candidate_recall_reference_count':33,'compatible_reference_count':eligible,'candidate_recall_among_compatible_references':{f'at_{k}':hits[k]/eligible if eligible else None for k in (5,10,20)},'cheese_controls':len(cheese),'cheese_changed_selections':sum(not r['unchanged'] for r in cheese),'before':{k:v for k,v in before.items() if k not in ('outcomes','candidate_traces')},'after':{k:v for k,v in after.items() if k not in ('outcomes','candidate_traces')},'holdout':{k:v for k,v in m.items() if k not in ('cases','immutable_review_hashes')},'verification':verification}
 (P/'report.json').write_text(json.dumps(summary,indent=2)+'\n')
 lines=['# Last focused structural correction pass','', '**STRUCTURAL_ISSUES_REMAIN**. This one correction pass, test execution, empirical evaluation and 300-case blank micro-holdout are complete. The next review must establish accuracy; changed selections were not automatically relabeled. No freeze/certification is claimed.','', '## Evidence and diagnoses','', 'The 700-case assistant QA CSV matches the original case IDs and immutable context; the issues file agrees with it. Counts: 523 CORRECT, 98 ACCEPTABLE_SUBSTITUTE, 38 WRONG, 33 SHOULD_HAVE_MATCHED, 8 AMBIGUOUS. Of 416 accepted decisions, 377 are good, 38 WRONG and one AMBIGUOUS. Accepted-good 90.625%; WRONG 9.135%; reviewed-reject SHOULD_HAVE_MATCHED 33/284 = 11.62%. These are assistant review labels, not independent human certification.','', 'All 38 WRONG rows were classified before matcher edits (wrong_root_causes.csv, root_causes.json and frozen source snapshots). One label contradiction remains explicit: “2 teaspoon unflavored gelatin” → unflavored gelatin is structurally valid; the note incorrectly calls it a flavored request. We preserved the supplied label, recorded disagreement, and kept a positive general regression. Cream of tartar remains a baking-acid identity distinct from dairy cream; six cream identities are tested separately.','', '| Root cause | Count |','|---|---:|']
 for cause,count in audit['wrong_root_cause_counts'].items():lines.append(f'| {cause} | {count} |')
 lines+=['', '## General rules and why they generalize','', '- Product heads: pastries, strudel, spreads, pâté/mousse, protein treats, crispy prepared products, seasoning and flavored-water derivatives dominate component ingredients. Unknown sauce/juice heads are guarded even when an inner component is a purchasable food. The 60-cell derivative matrix exercises ten heads across fruit, vegetable, meat, confection, sugar and grain. Legitimate named grocery identities remain purchasable.','- Nonfood: name and category/subcategory/status signals for household care, cleaners, polishes, cosmetics, pet goods and supplements hard-classify as nonfood before food parsing. Explicit adversarial names/categories yield zero food-compatible products in tests. This is a hard evidence gate, not a claim of perfect detection when inventory metadata/names omit all nonfood evidence.','- Taxonomy: spaghetti squash, snow peas, Brazil/breadfruit nuts, orange peel, cream sauce, hot pepper sauce/paste, tomato concentrate/passata, syrup and marshmallow fluff have separate heads/subfamilies. Canadian/back bacon is distinct from belly bacon. These are real taxonomy facts, independent of recipes, brands or SKU IDs.','- Required attributes: whole grain, microwave-ready form, flavored gelatin, reduced fat, candied treatment, smoked seasoning, peppercorn form and olive-oil grade are preserved. Fish flavors are gated like meat/dairy flavors. Generic queries can accept structurally compatible specifics, but a declared attribute must have product evidence.','- Preparation: explicitly requested cooked basic meat/vegetables/beans may be prepared from raw/base products as an equivalent, with species/cut, skin/bone, state and treatment gates intact. Mincing cured ham is kitchen preparation; grinding raw meat remains a purchased distinction. This is the user-requested cooking policy, not a globally weakened prepared-food gate.','- Normalization: conventional seasoning quantities/aliases, shared oil/form heads, non-food preparation annotations and separately quantified OR alternatives are parsed without dropping meaningful purchase attributes. Ambiguous slash-separated food options abstain. Family-first candidate filtering is preserved; new genuine aliases/identities (shallot, asparagus, Andouille, sauerkraut, crackers, chips, relish, raisins, ice, spaghettini) correct structural candidate starvation.','- Shopping mode: tamari and soy sauce are distinct by default and only explicit substitution mode can substitute them. Yukon Gold/russet remain different varieties. Double/heavy cream share the declared equivalent cream identity. Cheese hierarchy and strict default shopping mode remain unchanged.','', 'Each frozen root-cause row includes a review example, general rule and unseen witness classes. No query/SKU exceptions or IDs entered production. Product retrieval implementation, scoring weights and global thresholds are unchanged. Matcher/ontology versions are v3.2.','', '## Every material case and false-negative stage','', f'All 71 material rows have regressions with case_id, cause and general rule. 37 structurally wrong original pairs are blocked; the remaining row is the explicit unflavored-gelatin label disagreement. Of the 33 rejected assistant-labeled misses, {fn_accepted} now select a product; these are coverage recoveries, not new correctness labels.','', f'Candidate reference recall@5/@10/@20 over all 33 anchors: {hits[5]}/33, {hits[10]}/33, {hits[20]}/33. Among {eligible} structurally compatible reference pairs: {hits[5]}/{eligible}, {hits[10]}/{eligible}, {hits[20]}/{eligible}. References were explicitly adjudicated; replacements for incorrect first diagnostic alternatives are documented in regression/outcome files. Unsupported metadata references remain in the full denominator rather than being hidden.','', 'material_case_outcomes.json records every original first failure stage, chosen inventory anchor, post-fix gate, candidate rank, selection and remaining failure stage. Genuine unknown canned/fresh/dried/sodium evidence stays unverified. Generic vinegar references are structurally compatible but may still abstain on the existing material-identity margin policy; no threshold/margin rule was loosened just to recover those rows.','', '## Full actual population','', 'All 8,877 actual queries were evaluated using the final source. Frozen name-rule benchmarks are diagnostic proxies and were not used as a manual answer key.','', '| Metric | Before this pass | After |','|---|---:|---:|']
 def pct(x):return f'{100*x:.2f}%'
 for name,bv,av in [('Accepted',before['accepted'],after['accepted']),('Rejected',before['rejected'],after['rejected']),('No-match rate',pct(before['no_match_rate']),pct(after['no_match_rate']))]:lines.append(f'| {name} | {bv} | {av} |')
 for key,name in [('precision_proxy','Proxy precision'),('recall_proxy','Proxy recall'),('false_positive_rate_proxy','Wrong / scored accepted proxy'),('false_negative_rate_proxy','Abstained positives / scored positives proxy')]:lines.append(f'| {name} | {pct(before["top1_name_rule_proxy"]["all"][key])} | {pct(after["top1_name_rule_proxy"]["all"][key])} |')
 for key in ['wrong_family_count','prepared_food_fp','wrong_species_cut','attribute_leakage','state_form_mistakes']:lines.append(f'| Top-1 proxy {key} | {before["top1_name_rule_proxy"]["all"][key]} | {after["top1_name_rule_proxy"]["all"][key]} |')
 for key in ['warm_uncached_median_ms','warm_uncached_p95_ms']:lines.append(f'| {key} | {before["latency"][key]:.3f} | {after["latency"][key]:.3f} |')
 lines+=['', f'Confidence after: `{json.dumps(after["confidence_distribution"])}`. Acceptance rose by {after["accepted"]-before["accepted"]}; safety was not achieved by broadly rejecting more queries. Proxy precision/recall nevertheless declined and are reported without relabeling the benchmark. Two newly proxy-flagged selections are explicit egg/egg-mix OR queries selecting eggs; this illustrates label limitations, not an excuse to count all discrepancies correct. Unknown benchmark products remain unknown and are not scored as correct; the ambiguity-inclusive precision bound is {pct(after["top1_name_rule_proxy"]["all"]["precision_including_unlabelled_as_not_correct_proxy"])}.','', f'All {after["accepted"]} accepted outputs contain zero products classified as nonfood by the new ontology. This classifier-based scan is not independent human validation of product identities.', '', 'Latency uses the same 100 seeded, primed queries with result cache cleared per call; it excludes cold-start and end-to-end API overhead. Full distributions, category precision and pair-proxy results are retained in report.json and after_evaluation.json. No new manually adjudicated precision/FN rate is asserted.','', '## Tests and regressions','', '495/495 full-suite tests pass, including suite-order coverage. There are 71 new data regressions (2,015 total across four corpora) and eight new test methods with generated subcases. Separate requested suites:','', '| Suite | Tests | Result |','|---|---:|---|']
 for name,result in tests.items():lines.append(f'| {name} | {result["tests"]} | PASS |')
 lines+=['', f'Cheese: {len(cheese)} reviewed cheese-control rows across both cohorts; {summary["cheese_changed_selections"]} selection changes. See cheese_control_outcomes.json. Meat/cut tests preserve species, anatomical cut, processing and treatment. Nonfood adversarial tests have zero food-compatible outputs; no new independent human nonfood certification is implied.','', '## Final blank micro-holdout','', 'data/matcher_micro_holdout/review.csv: 300 cases, seed 20261012, 150 accepted Exact/High + 75 rejected + 75 disjoint hard cases. Labels are blank. Cases are drawn from actual matcher outputs with fixed structural strata; no correctness labels influence sampling.','', '| Hard stratum | Requested | Sampled | Eligible pool |','|---|---:|---:|---:|']
 for group,v in m['sample_counts'].items():
  if group.startswith('hard: '):lines.append(f'| {group[6:]} | {v["requested"]} | {v["sampled"]} | {m["hard_available_counts"][group[6:]]} |')
 lines+=['', f'Scarcity before redistribution: `{json.dumps(m["hard_quota_shortfalls_before_redistribution"])}`. The nonfood-boundary stratum samples food-query identities susceptible to nonfood token collisions, rather than fabricating selected nonfood errors; the generated test matrix separately exercises explicit nonfood adversaries.','', 'Independent verification found zero normalized-query overlap with old 950 QA, 1,100 structural holdout, 700 final holdout, all four regression corpora, real-recipe regressions, historical harvest and inventory benchmark. Quantities remain part of query identity; this is query-level disjointness, not independence of food concepts or ontology rules. All 300 queries are normalized-unique; labels, source/exclusion hashes and CSV/population fingerprints were verified (holdout_verification.json).','', 'Review with `.venv/bin/python scripts/review_matcher_human.py --directory data/matcher_micro_holdout`. The requested next-review targets remain unmeasured.','', '## Scope and stop','', '`git diff --check` passes. Only matcher internals, tests and matcher evaluation were edited; prior unrelated local changes were preserved. No staging, commit, push, stash, restore or revert was performed.','', '**STRUCTURAL_ISSUES_REMAIN**. Await the 300-case review, adjudicate unknown metadata and remaining proxy/margin discrepancies, and do not freeze on this evidence. This correction pass is complete; stop here.']
 (P/'report.md').write_text('\n'.join(lines)+'\n');print(json.dumps({k:summary[k] for k in ['recommendation','original_wrong_pairs_blocked','formerly_rejected_FN_now_selected','candidate_recall_at_5_10_20','compatible_reference_count','cheese_changed_selections']},indent=2))
if __name__=='__main__':main()
